type Catalog={id:string;name:string;country?:string|null;parent_id?:string|null;brand_id?:string|null;is_active?:boolean};
type Identifier={type:string;value:string;is_primary:boolean};
type ProductRecord=Record<string,any>;
type Definition={id:string;code:string;name:string;data_type:string;unit?:string;is_required:boolean;options:any[]};
const identifierOptions=[['ean8','EAN-8'],['upca','UPC-A'],['ean13','EAN-13'],['gtin14','GTIN-14'],['internal','Código interno'],['manufacturer_reference','Referencia fabricante'],['supplier_reference','Referencia proveedor'],['previous_code','Código anterior'],['other','Otro']];
const detailTabs=[
 {id:'variants',label:'Variantes',fields:[['variants','Variantes comerciales (JSON)']]},
 {id:'units',label:'Unidades',fields:[['base_unit','Unidad base'],['purchase_unit','Unidad de compra'],['sale_unit','Unidad de venta'],['storage_unit','Unidad de almacenamiento'],['unit_conversions','Conversiones entre unidades'],['units_per_box','Cantidad por caja'],['units_per_package','Cantidad por paquete'],['units_per_pallet','Cantidad por pallet'],['commercial_unit','Unidad comercial'],['decimal_precision','Precisión decimal']]},
 {id:'logistics',label:'Logística',fields:[['net_weight','Peso neto'],['gross_weight','Peso bruto'],['length','Largo'],['width','Ancho'],['height','Alto'],['volume','Volumen'],['weight_unit','Unidad de peso'],['dimension_unit','Unidad dimensional'],['packaging_type','Tipo de embalaje'],['stackable','Apilabilidad'],['handling_requirements','Manipulación especial'],['storage_conditions','Condiciones de almacenamiento']]},
 {id:'commercial',label:'Comercial',fields:[['retail_price','Precio minorista'],['distributor_price','Precio distribuidor'],['price_lists','Listas de precios y políticas (JSON)'],['allowed_discount','Descuento máximo (%)'],['minimum_price','Precio mínimo autorizado'],['target_margin','Margen objetivo (%)'],['currency','Moneda'],['price_valid_from','Vigencia desde'],['price_valid_until','Vigencia hasta']]},
 {id:'costs',label:'Costos',fields:[['reference_acquisition_cost','Costo de adquisición referencial'],['last_purchase_cost','Último costo de compra'],['average_cost','Costo promedio (consulta Inventario)'],['landed_import_cost','Costo nacionalizado (consulta Importaciones)'],['attributable_costs','Costos adicionales atribuibles'],['cost_notes','Notas de costos']]},
 {id:'suppliers',label:'Proveedores',fields:[]},
 {id:'import-classification',label:'Clasificación aduanera',fields:[]},
];

export default function ProductEditor({productId}:{productId?:string}){
 const {token,user,isLoading}=useAuth();const router=useRouter();const [activeTab,setActiveTab]=useState('general');const [busy,setBusy]=useState(false);const [uploading,setUploading]=useState(false);const [loading,setLoading]=useState(Boolean(productId));const [error,setError]=useState('');const [notice,setNotice]=useState('');const [product,setProduct]=useState<ProductRecord|null>(null);
 const [categories,setCategories]=useState<Catalog[]>([]);const [brands,setBrands]=useState<Catalog[]>([]);const [manufacturers,setManufacturers]=useState<Catalog[]>([]);const [models,setModels]=useState<Catalog[]>([]);const [families,setFamilies]=useState<Catalog[]>([]);const [definitions,setDefinitions]=useState<Definition[]>([]);const [history,setHistory]=useState<any[]>([]);
 const [variants,setVariants]=useState<ProductRecord[]>([]);const [units,setUnits]=useState<ProductRecord[]>([]);const [conversions,setConversions]=useState<ProductRecord[]>([]);const [logisticsHistory,setLogisticsHistory]=useState<ProductRecord[]>([]);const [variantAttributeValues,setVariantAttributeValues]=useState<Record<string,any>>({});const [variantForm,setVariantForm]=useState({name:'',sku:'',variant_label:'',barcode:'',sale_price:'',image_url:''});const [unitForm,setUnitForm]=useState({unit_code:'',name:'',dimension:'count',precision_scale:'0',is_base:false});const [conversionForm,setConversionForm]=useState({from_unit_id:'',to_unit_id:'',factor:'',valid_from:new Date().toISOString().slice(0,10),reason:''});const [conversionAmount,setConversionAmount]=useState('1');const [conversionResult,setConversionResult]=useState('');const [logisticsForm,setLogisticsForm]=useState<ProductRecord>({weight_unit:'kg',dimension_unit:'cm'});
 const [supplierLinks,setSupplierLinks]=useState<ProductRecord[]>([]);const [supplierOptions,setSupplierOptions]=useState<Catalog[]>([]);const [classificationRecords,setClassificationRecords]=useState<ProductRecord[]>([]);const [supplierForm,setSupplierForm]=useState<ProductRecord>({supplier_id:'',currency:'USD',valid_from:new Date().toISOString().slice(0,10),is_preferred:false});const [classificationForm,setClassificationForm]=useState<ProductRecord>({tariff_heading:'',valid_from:new Date().toISOString().slice(0,10),source_name:'',source_url:'',evidence_url:''});
 const [mediaRecords,setMediaRecords]=useState<ProductRecord[]>([]);const [mediaForm,setMediaForm]=useState({media_type:'gallery',description:'',is_primary:false,sort_order:'0'});const [mediaPreview,setMediaPreview]=useState<{url:string;mime:string;name:string}|null>(null);
 const [form,setForm]=useState<ProductRecord>({name:'',commercial_name:'',sku:'',short_description:'',description:'',product_type:'physical',category_id:'',brand_id:'',manufacturer_id:'',model_id:'',family_id:'',reference:'',sale_price:'',cost_price:'',wholesale_price:'',iva_rate:'15',is_active:true,image_url:'',details:{}});
 const [identifiers,setIdentifiers]=useState<Identifier[]>([{type:'ean13',value:'',is_primary:true}]);const [attributeValues,setAttributeValues]=useState<Record<string,any>>({});
 const canWrite=user?.role==='admin'||user?.permissions?.includes('products.write');const canApproveConversions=user?.role==='admin'||user?.roles?.some(role=>['admin','erp_admin','inventory_manager'].includes(role));const canReviewClassification=user?.role==='admin'||user?.roles?.some(role=>['admin','erp_admin','imports_manager','jefe_importaciones'].includes(role));
 useEffect(()=>()=>{if(mediaPreview?.url)URL.revokeObjectURL(mediaPreview.url);},[mediaPreview?.url]);
 useEffect(()=>{if(!isLoading&&!token)router.replace('/login');},[isLoading,token,router]);
 useEffect(()=>{if(!token)return;void loadCatalogs();if(productId)void loadProduct();},[token,productId]);
 const loadCatalogs=async()=>{try{const headers={Authorization:`Bearer ${token}`};const [c,b,m,mo,f]=await Promise.all(['categories','brands','manufacturers','models','families'].map(async type=>{const response=await fetch(`/api/product-catalog/${type}`,{headers});if(!response.ok)throw new Error('No se pudieron cargar los catálogos.');return response.json();}));setCategories(c.filter((x:Catalog)=>x.is_active!==false));setBrands(b.filter((x:Catalog)=>x.is_active!==false));setManufacturers(m.filter((x:Catalog)=>x.is_active!==false));setModels(mo.filter((x:Catalog)=>x.is_active!==false));setFamilies(f.filter((x:Catalog)=>x.is_active!==false));}catch(e){setError(e instanceof Error?e.message:'Error al cargar los catálogos.');}};
 const loadProduct=async()=>{setLoading(true);try{const headers={Authorization:`Bearer ${token}`};const response=await fetch(`/api/products/${productId}`,{headers});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo cargar el producto.');setProduct(data);setForm({...data,commercial_name:data.commercial_name||data.name,category_id:data.category_id||'',brand_id:data.brand_id||'',manufacturer_id:data.manufacturer_id||'',model_id:data.model_id||'',family_id:data.family_id||'',sale_price:String(data.sale_price??data.price??0),cost_price:String(data.cost_price??0),wholesale_price:data.wholesale_price==null?'':String(data.wholesale_price),iva_rate:String(data.iva_rate??13),image_url:data.image_url||'',details:data.details||{}});
   const [ir,ar,hr,vr,ur,lr,lhr,sr,cr,so,mr]=await Promise.all([fetch(`/api/products/${productId}/identifiers`,{headers}),fetch(`/api/products/${productId}/attributes`,{headers}),fetch(`/api/products/${productId}/history`,{headers}),fetch(`/api/products/${productId}/variants`,{headers}),fetch(`/api/products/${productId}/units`,{headers}),fetch(`/api/products/${productId}/logistics`,{headers}),fetch(`/api/products/${productId}/logistics/history`,{headers}),fetch(`/api/products/${productId}/suppliers`,{headers}),fetch(`/api/products/${productId}/import-classifications`,{headers}),fetch(`/api/products/${productId}/supplier-options`,{headers}),fetch(`/api/products/${productId}/media`,{headers})]);const ids=ir.ok?await ir.json():[];setIdentifiers(ids.length?ids.map((x:any)=>({type:x.identifier_type,value:x.value,is_primary:x.is_primary})): [{type:'ean13',value:'',is_primary:true}]);const attrs=ar.ok?await ar.json():[];setAttributeValues(Object.fromEntries(attrs.map((x:any)=>[x.definition_id,x.value])));setHistory(hr.ok?await hr.json():[]);setVariants(vr.ok?await vr.json():[]);const unitData=ur.ok?await ur.json():{units:[],conversions:[]};setUnits(unitData.units||[]);setConversions(unitData.conversions||[]);setLogisticsHistory(lhr.ok?await lhr.json():[]);setSupplierLinks(sr.ok?await sr.json():[]);setClassificationRecords(cr.ok?await cr.json():[]);setSupplierOptions(so.ok?await so.json():[]);setMediaRecords(mr.ok?await mr.json():[]);const logistics=lr.ok?await lr.json():null;if(logistics){const nextValidFrom=new Date(`${String(logistics.valid_from).slice(0,10)}T00:00:00Z`);nextValidFrom.setUTCDate(nextValidFrom.getUTCDate()+1);setLogisticsForm({...logistics,valid_from:nextValidFrom.toISOString().slice(0,10)});}
  }catch(e){setError(e instanceof Error?e.message:'Error al cargar el producto.');}finally{setLoading(false);}};
 useEffect(()=>{if(!token||!form.category_id)return;let cancelled=false;fetch(`/api/product-catalog/categories/${form.category_id}/attributes`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.ok?r.json():[]).then((rows:Definition[])=>{if(!cancelled)setDefinitions(rows);}).catch(()=>{if(!cancelled)setDefinitions([]);});return()=>{cancelled=true;};},[token,form.category_id]);
 const categoryOptions=useMemo(()=>categories.map(category=>{let depth=0;let parent=category.parent_id;while(parent&&depth<12){depth++;parent=categories.find(item=>item.id===parent)?.parent_id||null;}return { ...category,depth };}),[categories]);
 const modelsForBrand=models.filter(model=>!model.brand_id||model.brand_id===form.brand_id);
 const updateDetail=(key:string,value:any)=>setForm((current:any)=>({...current,details:{...(current.details||{}),[key]:value}}));
 const changeCategory=(categoryId:string)=>{if(form.category_id&&categoryId!==form.category_id&&Object.keys(attributeValues).length){const confirmed=window.confirm('Al cambiar la categoría se reemplazarán los atributos aplicables. Los valores actuales se conservarán en el historial de datos del producto. ¿Continuar?');if(!confirmed)return;const preserved=definitions.filter(d=>attributeValues[d.id]!==undefined&&attributeValues[d.id]!==''&&attributeValues[d.id]!==null).map(d=>({code:d.code,name:d.name,value:attributeValues[d.id]}));setForm((current:any)=>({...current,category_id:categoryId,details:{...(current.details||{}),previous_category_attributes:[...(current.details?.previous_category_attributes||[]),...preserved]}}));}else setForm({...form,category_id:categoryId});setAttributeValues({});};
 const uploadFile=async(key:string,file?:File)=>{if(!file)return;setUploading(true);setError('');try{const body=new FormData();body.append('file',file);const response=await fetch('/api/products/upload',{method:'POST',headers:{Authorization:`Bearer ${token}`},body});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo subir el archivo.');if(key==='image_url')setForm((current:any)=>({...current,image_url:data.url}));else updateDetail(key,[...(form.details?.[key]||[]),{url:data.url,name:data.name,mime_type:data.mime_type,size:data.size}]);}catch(e){setError(e instanceof Error?e.message:'Error al subir el archivo.');}finally{setUploading(false);}};
 const createSku=()=>{const base=String(form.commercial_name||form.name||'PROD').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,42)||'PROD';setForm({...form,sku:`${base}-${Math.random().toString(36).slice(2,6).toUpperCase()}`});};
 const save=async(event:FormEvent)=>{event.preventDefault();setBusy(true);setError('');setNotice('');try{if(!String(form.name||'').trim())throw new Error('El nombre interno es obligatorio.');if(form.sale_price===''||Number(form.sale_price)<0)throw new Error('Indica un precio de venta válido.');const ids=identifiers.filter(item=>item.value.trim());const primary=ids.filter(item=>item.is_primary);if(primary.length>1)throw new Error('Solo se admite un identificador principal.');const payload={...form,name:String(form.name).trim(),commercial_name:String(form.commercial_name||form.name).trim(),price:Number(form.sale_price||0),sale_price:Number(form.sale_price||0),cost_price:Number(form.cost_price||0),wholesale_price:form.wholesale_price===''?null:Number(form.wholesale_price),iva_rate:Number(form.iva_rate),category:categories.find(x=>x.id===form.category_id)?.name||null,brand:brands.find(x=>x.id===form.brand_id)?.name||null,identifiers:ids,attribute_values:definitions.filter(d=>attributeValues[d.id]!==undefined&&attributeValues[d.id]!==''&&attributeValues[d.id]!==null).map(d=>({definition_id:d.id,value:attributeValues[d.id]})),change_reason:form.change_reason||undefined};const response=await fetch(productId?`/api/products/${productId}`:'/api/products',{method:productId?'PATCH':'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo guardar el producto.');setNotice('Producto guardado.');if(!productId)router.replace(`/products/${data.id}`);setProduct(data);if(productId)await loadProduct();}catch(e){setError(e instanceof Error?e.message:'Error al guardar.');}finally{setBusy(false);}};
 const archive=async()=>{if(!productId)return;const reason=window.prompt('Motivo para archivar este producto:');if(!reason?.trim())return;setBusy(true);try{const response=await fetch(`/api/products/${productId}/archive`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({reason})});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo archivar el producto.');setProduct(data);setNotice('Producto archivado.');}catch(e){setError(e instanceof Error?e.message:'No se pudo archivar.');}finally{setBusy(false);}};
 const restore=async()=>{if(!productId)return;const reason=window.prompt('Motivo para restaurar este producto:');if(!reason?.trim())return;setBusy(true);try{const response=await fetch(`/api/products/${productId}/restore`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({reason})});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo restaurar.');setProduct(data);setForm(data);setNotice('Producto restaurado como inactivo.');}catch(e){setError(e instanceof Error?e.message:'No se pudo restaurar.');}finally{setBusy(false);}};
 const toggleActive=async()=>{if(!productId||!product)return;const reason=window.prompt(`Motivo para ${product.is_active?'desactivar':'activar'} el producto:`)||'';if(!reason.trim())return;setBusy(true);try{const response=await fetch(`/api/products/${productId}/status`,{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({is_active:!product.is_active,reason})});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo cambiar el estado.');setProduct({...product,is_active:data.is_active});setNotice(data.is_active?'Producto activado.':'Producto desactivado.');await loadProduct();}catch(e){setError(e instanceof Error?e.message:'No se pudo cambiar el estado.');}finally{setBusy(false);}};
 const phase2Request=async(path:string,method:string,body?:any)=>{const response=await fetch(path,{method,headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo guardar.');return data;};
 const createVariant=async(event:FormEvent)=>{event.preventDefault();if(!productId)return;setBusy(true);setError('');try{const attribute_values=definitions.filter(d=>variantAttributeValues[d.id]!==undefined&&variantAttributeValues[d.id]!==''&&variantAttributeValues[d.id]!==null).map(d=>({definition_id:d.id,value:variantAttributeValues[d.id]}));const barcode=variantForm.barcode.trim();const barcodeType=({8:'ean8',12:'upca',13:'ean13',14:'gtin14'} as Record<number,string>)[barcode.replace(/\D/g,'').length]||'internal';const data=await phase2Request(`/api/products/${productId}/variants`,'POST',{...variantForm,name:variantForm.name||variantForm.variant_label,commercial_name:variantForm.name||variantForm.variant_label,sale_price:variantForm.sale_price===''?undefined:Number(variantForm.sale_price),identifiers:barcode?[{type:barcodeType,value:barcode,is_primary:barcodeType!=='internal'}]:[],attribute_values,details:{variant_label:variantForm.variant_label||variantForm.name}});setVariants(current=>[...current,data]);setVariantForm({name:'',sku:'',variant_label:'',barcode:'',sale_price:'',image_url:''});setVariantAttributeValues({});setNotice('Variante creada como producto independiente para Inventario.');}catch(e){setError(e instanceof Error?e.message:'No se pudo crear la variante.');}finally{setBusy(false);}};
 const addUnit=async(event:FormEvent)=>{event.preventDefault();if(!productId)return;setBusy(true);setError('');try{const data=await phase2Request(`/api/products/${productId}/units`,'POST',{...unitForm,precision_scale:Number(unitForm.precision_scale)});setUnits(current=>[...current.filter(x=>!data.is_base||!x.is_base),data]);setUnitForm({unit_code:'',name:'',dimension:'count',precision_scale:'0',is_base:false});setNotice('Unidad agregada.');}catch(e){setError(e instanceof Error?e.message:'No se pudo agregar la unidad.');}finally{setBusy(false);}};
 const addConversion=async(event:FormEvent)=>{event.preventDefault();if(!productId)return;setBusy(true);setError('');try{const data=await phase2Request(`/api/products/${productId}/unit-conversions`,'POST',{...conversionForm});setConversions(current=>[data,...current]);setConversionForm(current=>({...current,factor:'',reason:''}));setNotice(data.status==='pending'?'Conversión enviada a aprobación de Inventario.':'Conversión vigente guardada.');}catch(e){setError(e instanceof Error?e.message:'No se pudo guardar la conversión.');}finally{setBusy(false);}};
 const approveConversion=async(id:string)=>{if(!productId)return;setBusy(true);setError('');try{const data=await phase2Request(`/api/products/${productId}/unit-conversions/${id}/approval`,'POST');setConversions(current=>current.map(item=>item.id===id?data:item));setNotice('Conversión aprobada.');}catch(e){setError(e instanceof Error?e.message:'No se pudo aprobar la conversión.');}finally{setBusy(false);}};
 const addSupplierLink=async(event:FormEvent)=>{event.preventDefault();if(!productId)return;setBusy(true);setError('');try{const data=await phase2Request(`/api/products/${productId}/suppliers`,'POST',{...supplierForm,quoted_unit_cost:supplierForm.quoted_unit_cost===''?null:Number(supplierForm.quoted_unit_cost),minimum_order_quantity:supplierForm.minimum_order_quantity===''?null:Number(supplierForm.minimum_order_quantity),lead_time_days:supplierForm.lead_time_days===''?null:Number(supplierForm.lead_time_days)});setSupplierLinks(rows=>[data,...rows]);setSupplierForm({supplier_id:'',currency:'USD',valid_from:new Date().toISOString().slice(0,10),is_preferred:false});setNotice('Referencia de proveedor guardada.');}catch(e){setError(e instanceof Error?e.message:'No se pudo guardar el proveedor del producto.');}finally{setBusy(false);}};
 const submitClassification=async(event:FormEvent)=>{event.preventDefault();if(!productId)return;setBusy(true);setError('');try{const data=await phase2Request(`/api/products/${productId}/import-classifications`,'POST',{...classificationForm,customs_weight:classificationForm.customs_weight===''?null:Number(classificationForm.customs_weight)});setClassificationRecords(rows=>[data,...rows]);setClassificationForm({tariff_heading:'',valid_from:new Date().toISOString().slice(0,10),source_name:'',source_url:'',evidence_url:''});setNotice('Clasificación enviada a revisión. No se usa hasta su aprobación.');}catch(e){setError(e instanceof Error?e.message:'No se pudo enviar la clasificación.');}finally{setBusy(false);}};
 const reviewClassification=async(id:string,decision:'approved'|'rejected')=>{if(!productId)return;const reason=decision==='rejected'?window.prompt('Motivo del rechazo:')||'':'';if(decision==='rejected'&&!reason.trim())return;setBusy(true);setError('');try{const data=await phase2Request(`/api/products/${productId}/import-classifications/${id}/review`,'POST',{decision,reason});setClassificationRecords(rows=>rows.map(row=>row.id===id?data:row));setNotice(decision==='approved'?'Clasificación aprobada y vigente.':'Clasificación rechazada.');}catch(e){setError(e instanceof Error?e.message:'No se pudo revisar la clasificación.');}finally{setBusy(false);}};
 const uploadClassificationEvidence=async(event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(!file)return;setUploading(true);setError('');try{const body=new FormData();body.append('file',file);const response=await fetch('/api/products/upload',{method:'POST',headers:{Authorization:`Bearer ${token}`},body});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo subir la evidencia.');setClassificationForm(current=>({...current,evidence_url:data.url}));}catch(e){setError(e instanceof Error?e.message:'No se pudo subir la evidencia.');}finally{setUploading(false);}};
 const uploadProductMedia=async(event:ChangeEvent<HTMLInputElement>,mediaId?:string)=>{if(!productId)return;const file=event.target.files?.[0];if(!file)return;const reason=mediaId?window.prompt('Motivo para reemplazar esta versión:')||'':'';if(mediaId&&!reason.trim())return;setUploading(true);setError('');try{const body=new FormData();body.append('file',file);if(mediaId){body.append('reason',reason);}else{body.append('media_type',mediaForm.media_type);body.append('description',mediaForm.description);body.append('is_primary',String(mediaForm.is_primary));body.append('sort_order',mediaForm.sort_order);}const endpoint=mediaId?`/api/products/${productId}/media/${mediaId}/versions`:`/api/products/${productId}/media`;const response=await fetch(endpoint,{method:'POST',headers:{Authorization:`Bearer ${token}`},body});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo guardar el archivo.');setMediaRecords(rows=>[data,...rows.filter(row=>row.id!==data.id)]);const audit=await fetch(`/api/products/${productId}/history`,{headers:{Authorization:`Bearer ${token}`}});if(audit.ok)setHistory(await audit.json());setMediaForm({media_type:'gallery',description:'',is_primary:false,sort_order:'0'});setNotice(mediaId?'Nueva versión guardada; las versiones anteriores siguen disponibles.':'Archivo asociado al producto.');event.target.value='';}catch(e){setError(e instanceof Error?e.message:'No se pudo guardar el archivo.');}finally{setUploading(false);}};
 const openMediaVersion=async(mediaId:string,versionId:string)=>{if(!productId)return;try{const response=await fetch(`/api/products/${productId}/media/${mediaId}/versions/${versionId}/download`,{headers:{Authorization:`Bearer ${token}`}});if(!response.ok)throw new Error('No se pudo descargar la versión.');const blob=await response.blob();const url=URL.createObjectURL(blob);setMediaPreview(current=>{if(current?.url)URL.revokeObjectURL(current.url);return {url,mime:blob.type,name:response.headers.get('content-disposition')||'Archivo'};});}catch(e){setError(e instanceof Error?e.message:'No se pudo abrir el archivo.');}};
 const archiveMedia=async(mediaId:string)=>{if(!productId)return;const reason=window.prompt('Motivo para archivar el archivo:')||'';if(!reason.trim())return;setBusy(true);try{const response=await fetch(`/api/products/${productId}/media/${mediaId}/archive`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({reason})});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo archivar el archivo.');setMediaRecords(rows=>rows.filter(row=>row.id!==mediaId));const audit=await fetch(`/api/products/${productId}/history`,{headers:{Authorization:`Bearer ${token}`}});if(audit.ok)setHistory(await audit.json());setNotice('Archivo archivado. El historial de versiones se conserva.');}catch(e){setError(e instanceof Error?e.message:'No se pudo archivar el archivo.');}finally{setBusy(false);}};
 const saveLogistics=async(event:FormEvent)=>{event.preventDefault();if(!productId)return;setBusy(true);setError('');try{const numeric=['net_weight','gross_weight','length','width','height','volume','units_per_box','units_per_package','units_per_pallet'];const payload={...logisticsForm};for(const key of numeric)payload[key]=payload[key]===''||payload[key]===undefined?null:Number(payload[key]);const data=await phase2Request(`/api/products/${productId}/logistics`,'POST',payload);setLogisticsForm(data);setLogisticsHistory(current=>[data,...current.filter(item=>item.id!==data.id)]);setNotice('Perfil logístico guardado con nueva vigencia.');}catch(e){setError(e instanceof Error?e.message:'No se pudo guardar el perfil logístico.');}finally{setBusy(false);}};
 const uploadVariantImage=async(file?:File)=>{if(!file)return;setUploading(true);setError('');try{const body=new FormData();body.append('file',file);const response=await fetch('/api/products/upload',{method:'POST',headers:{Authorization:`Bearer ${token}`},body});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo subir la fotografía.');setVariantForm(current=>({...current,image_url:data.url}));}catch(e){setError(e instanceof Error?e.message:'No se pudo subir la fotografía.');}finally{setUploading(false);}};
 const runConversion=async()=>{if(!productId||!conversionForm.from_unit_id||!conversionForm.to_unit_id)return;setBusy(true);setError('');try{const data=await phase2Request(`/api/products/${productId}/units/convert`,'POST',{amount:conversionAmount,from_unit_id:conversionForm.from_unit_id,to_unit_id:conversionForm.to_unit_id});setConversionResult(String(data.amount));}catch(e){setError(e instanceof Error?e.message:'No se pudo convertir la cantidad.');}finally{setBusy(false);}};
 const addIdentifier=()=>setIdentifiers(current=>[...current,{type:'internal',value:'',is_primary:false}]);
 const tabs=[['general','General'],['identification','Identificación'],['attributes','Atributos'],...detailTabs.map(({id,label})=>[id,label]),['media','Fotos y documentos'],...(productId?[['history','Historial']]:[])];
 return <div className="dashboard-layout"><Navbar/><main className="dashboard-content products-page product-editor-page"><header className="product-editor-heading"><div><p className="eyebrow">CATÁLOGO COMERCIAL</p><h1>{productId?'Ficha del producto':'Crear producto'}</h1><p>{product?.sku||'Completa la información maestra del catálogo.'}</p></div><div className="product-heading-actions"><button className="settings-secondary-button" onClick={()=>router.push('/products')}><ArrowLeft size={15}/>Volver al catálogo</button>{canWrite&&productId&&!product?.archived_at&&<><button className="settings-secondary-button" disabled={busy} onClick={()=>void toggleActive()}>{product?.is_active?'Desactivar':'Activar'}</button><button className="settings-secondary-button" disabled={busy} onClick={()=>void archive()}><Archive size={15}/>Archivar</button></>}{canWrite&&productId&&product?.archived_at&&<button className="settings-primary-button" disabled={busy} onClick={()=>void restore()}>Restaurar</button>}</div></header>
  {loading?<div className="settings-loading">Cargando producto…</div>:<section className="product-editor-card"><nav className="product-form-tabs">{tabs.map(([id,label])=><button type="button" key={id} className={activeTab===id?'active':''} onClick={()=>setActiveTab(id)}>{label}</button>)}</nav>
   {activeTab==='history'?<div className="product-history-list">{history.length?history.map(entry=><article key={entry.id}><div><strong>{entry.action==='created'?'Producto creado':entry.action==='archived'?'Producto archivado':entry.action==='restored'?'Producto restaurado':entry.field_name?`Cambio en ${entry.field_name}`:entry.action}</strong><small>{entry.actor_name||'Usuario'} · {new Date(entry.created_at).toLocaleString('es-EC')}{entry.reason?` · ${entry.reason}`:''}{entry.correlation_id?` · Operación ${String(entry.correlation_id).slice(0,8)}`:''}</small></div>{entry.before_value!==null&&<code>{JSON.stringify(entry.before_value)} → {JSON.stringify(entry.after_value)}</code>}</article>):<p>No hay cambios registrados.</p>}</div>:<form noValidate onSubmit={save}><div className="product-editor-panel">
    {activeTab==='general'&&<div className="settings-form-grid"><label className="settings-field"><span>Nombre interno *</span><input maxLength={100} required value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/></label><label className="settings-field"><span>Nombre comercial</span><input maxLength={160} value={form.commercial_name||''} onChange={e=>setForm({...form,commercial_name:e.target.value})}/></label><label className="settings-field"><span>SKU</span><div className="product-sku-control"><input maxLength={50} value={form.sku||''} onChange={e=>setForm({...form,sku:e.target.value})}/><button type="button" className="settings-secondary-button" onClick={createSku}>Generar</button></div></label><label className="settings-field"><span>Tipo de artículo</span><select value={form.product_type||'physical'} onChange={e=>setForm({...form,product_type:e.target.value})}><option value="physical">Producto físico</option><option value="service">Servicio</option><option value="combo">Combo / kit</option><option value="sample">Muestra</option></select></label><label className="settings-field"><span>Categoría</span><select value={form.category_id||''} onChange={e=>changeCategory(e.target.value)}><option value="">Sin categoría</option>{categoryOptions.map(c=><option key={c.id} value={c.id}>{'　'.repeat(c.depth)}{c.name}</option>)}</select></label><label className="settings-field"><span>Marca</span><select value={form.brand_id||''} onChange={e=>setForm({...form,brand_id:e.target.value,model_id:''})}><option value="">Sin marca</option>{brands.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label className="settings-field"><span>Fabricante</span><select value={form.manufacturer_id||''} onChange={e=>setForm({...form,manufacturer_id:e.target.value})}><option value="">Sin fabricante</option>{manufacturers.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label className="settings-field"><span>Modelo</span><select value={form.model_id||''} onChange={e=>setForm({...form,model_id:e.target.value})}><option value="">Sin modelo</option>{modelsForBrand.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label className="settings-field"><span>Familia</span><select value={form.family_id||''} onChange={e=>setForm({...form,family_id:e.target.value})}><option value="">Sin familia</option>{families.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label className="settings-field"><span>Referencia</span><input value={form.reference||''} onChange={e=>setForm({...form,reference:e.target.value})}/></label><label className="settings-field"><span>Precio de venta *</span><input type="number" min="0" step="0.01" value={form.sale_price} onChange={e=>setForm({...form,sale_price:e.target.value})}/></label><label className="settings-field"><span>Costo de referencia</span><input type="number" min="0" step="0.01" value={form.cost_price} onChange={e=>setForm({...form,cost_price:e.target.value})}/></label><label className="settings-field"><span>Precio mayorista</span><input type="number" min="0" step="0.01" value={form.wholesale_price||''} onChange={e=>setForm({...form,wholesale_price:e.target.value})}/></label><label className="settings-field"><span>IVA (%)</span><input type="number" min="0" max="15" step="0.01" value={form.iva_rate} onChange={e=>setForm({...form,iva_rate:e.target.value})}/></label><label className="settings-field product-editor-full"><span>Descripción breve</span><input maxLength={500} value={form.short_description||''} onChange={e=>setForm({...form,short_description:e.target.value})}/></label><label className="settings-field product-editor-full"><span>Descripción</span><textarea rows={4} value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></label></div>}
    {activeTab==='identification'&&<div className="product-identifier-editor"><header><div><h2>Códigos del producto</h2><p>El identificador principal debe ser un GTIN válido; los demás pueden ser referencias internas o de proveedor.</p></div><button type="button" className="settings-secondary-button" onClick={addIdentifier}><Plus size={15}/>Agregar código</button></header>{identifiers.map((item,index)=><div className="product-identifier-row" key={index}><select value={item.type} onChange={e=>setIdentifiers(current=>current.map((x,i)=>i===index?{...x,type:e.target.value}:x))}>{identifierOptions.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select><input placeholder="Código" value={item.value} onChange={e=>setIdentifiers(current=>current.map((x,i)=>i===index?{...x,value:e.target.value}:x))}/><label><input type="radio" name="primary-identifier" checked={item.is_primary} onChange={()=>setIdentifiers(current=>current.map((x,i)=>({...x,is_primary:i===index})))}/>Principal</label>{identifiers.length>1&&<button type="button" aria-label="Eliminar código" onClick={()=>setIdentifiers(current=>current.filter((_,i)=>i!==index))}><X size={15}/></button>}</div>)}</div>}
    {activeTab==='attributes'&&<div className="settings-form-grid">{!form.category_id?<p className="settings-modal-note">Selecciona una categoría para cargar sus atributos.</p>:definitions.length?definitions.map(definition=><label className="settings-field" key={definition.id}><span>{definition.name}{definition.is_required?' *':''}{definition.unit?` (${definition.unit})`:''}</span>{definition.data_type==='select'?<select required={definition.is_required} value={attributeValues[definition.id]??''} onChange={e=>setAttributeValues({...attributeValues,[definition.id]:e.target.value})}><option value="">Selecciona…</option>{(definition.options||[]).map((option:any)=><option key={String(option)} value={String(option)}>{String(option)}</option>)}</select>:definition.data_type==='multiselect'?<select multiple value={attributeValues[definition.id]||[]} onChange={e=>setAttributeValues({...attributeValues,[definition.id]:[...e.target.selectedOptions].map(o=>o.value)})}>{(definition.options||[]).map((option:any)=><option key={String(option)} value={String(option)}>{String(option)}</option>)}</select>:definition.data_type==='boolean'?<input type="checkbox" checked={Boolean(attributeValues[definition.id])} onChange={e=>setAttributeValues({...attributeValues,[definition.id]:e.target.checked})}/>:<input required={definition.is_required} type={definition.data_type==='date'?'date':definition.data_type==='number'||definition.data_type==='decimal'?'number':'text'} step={definition.data_type==='decimal'?'any':undefined} value={attributeValues[definition.id]??''} onChange={e=>setAttributeValues({...attributeValues,[definition.id]:e.target.value})}/>}</label>):<p className="settings-modal-note">Esta categoría aún no tiene atributos definidos. Créelos en Categorías y marcas.</p>}</div>}
    {activeTab==='variants'&&<div className="product-phase2-panel"><header className="product-phase2-heading"><div><h2>Variantes comercializables</h2><p>Cada variante se crea como producto hijo con SKU e identidad propia, para que Inventario pueda asignarle lotes y existencias independientes.</p></div></header>{productId?<><form className="product-phase2-form" onSubmit={createVariant}><div className="settings-form-grid"><label className="settings-field"><span>Nombre de la variante *</span><input required value={variantForm.name} onChange={e=>setVariantForm({...variantForm,name:e.target.value,variant_label:e.target.value})} placeholder="Camiseta negra talla M"/></label><label className="settings-field"><span>SKU propio *</span><div className="product-sku-control"><input required value={variantForm.sku} onChange={e=>setVariantForm({...variantForm,sku:e.target.value})}/><button type="button" className="settings-secondary-button" onClick={()=>{const base=`${form.sku||form.name||'VAR'}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,'-').slice(0,35);setVariantForm({...variantForm,sku:`${base}-${Math.random().toString(36).slice(2,6).toUpperCase()}`});}}>Generar</button></div></label><label className="settings-field"><span>Precio de venta (opcional)</span><input type="number" min="0" step="0.01" value={variantForm.sale_price} onChange={e=>setVariantForm({...variantForm,sale_price:e.target.value})}/></label><label className="settings-field"><span>Identificador alternativo</span><input value={variantForm.barcode} onChange={e=>setVariantForm({...variantForm,barcode:e.target.value})} placeholder="Código de barras"/></label><label className="settings-field"><span>Fotografía de variante</span><input type="file" accept="image/*" onChange={e=>void uploadVariantImage(e.target.files?.[0])}/>{variantForm.image_url&&<img className="product-editor-image-preview" src={variantForm.image_url} alt="Fotografía de la variante"/>}</label>{definitions.map(definition=><label className="settings-field" key={definition.id}><span>{definition.name}{definition.is_required?' *':''}{definition.unit?` (${definition.unit})`:''}</span>{definition.data_type==='select'?<select required={definition.is_required} value={variantAttributeValues[definition.id]??''} onChange={e=>setVariantAttributeValues({...variantAttributeValues,[definition.id]:e.target.value})}><option value="">Selecciona…</option>{(definition.options||[]).map((option:any)=><option key={String(option)} value={String(option)}>{String(option)}</option>)}</select>:definition.data_type==='multiselect'?<select multiple value={variantAttributeValues[definition.id]||[]} onChange={e=>setVariantAttributeValues({...variantAttributeValues,[definition.id]:[...e.target.selectedOptions].map(o=>o.value)})}>{(definition.options||[]).map((option:any)=><option key={String(option)} value={String(option)}>{String(option)}</option>)}</select>:definition.data_type==='boolean'?<input type="checkbox" checked={Boolean(variantAttributeValues[definition.id])} onChange={e=>setVariantAttributeValues({...variantAttributeValues,[definition.id]:e.target.checked})}/>:<input required={definition.is_required} type={definition.data_type==='date'?'date':definition.data_type==='number'||definition.data_type==='decimal'?'number':'text'} step={definition.data_type==='decimal'?'any':undefined} value={variantAttributeValues[definition.id]??''} onChange={e=>setVariantAttributeValues({...variantAttributeValues,[definition.id]:e.target.value})}/>}</label>)}</div><button className="settings-primary-button" disabled={busy||uploading}><Plus size={15}/>{uploading?'Subiendo imagen…':'Crear variante'}</button></form><div className="product-phase2-list">{variants.length?variants.map(variant=><article key={variant.id}>{variant.image_url?<img src={variant.image_url} alt=""/>:<span className="product-phase2-avatar">{String(variant.name||'?').slice(0,1)}</span>}<div><strong>{variant.commercial_name||variant.name}</strong><small>SKU {variant.sku||'—'} · {variant.is_active?'Activa':'Inactiva'} · {variant.barcode||'Sin código'}</small></div><button className="settings-secondary-button" onClick={()=>router.push(`/products/${variant.id}`)}>Abrir ficha</button></article>):<p>Aún no hay variantes para este producto.</p>}</div></>:<p className="settings-modal-note">Guarda primero el producto padre. Después podrás crear variantes con SKU, código, atributos e imagen propios.</p>}</div>}
    {activeTab==='units'&&<div className="product-phase2-panel"><header className="product-phase2-heading"><div><h2>Unidades y conversiones</h2><p>Define una unidad base y factores dirigidos. Las conversiones nuevas no reescriben cantidades históricas.</p></div></header>{productId?<><form className="product-phase2-form" onSubmit={addUnit}><div className="settings-form-grid"><label className="settings-field"><span>Código *</span><input required maxLength={32} value={unitForm.unit_code} onChange={e=>setUnitForm({...unitForm,unit_code:e.target.value})} placeholder="unidad"/></label><label className="settings-field"><span>Nombre *</span><input required value={unitForm.name} onChange={e=>setUnitForm({...unitForm,name:e.target.value})} placeholder="Unidad"/></label><label className="settings-field"><span>Magnitud</span><select value={unitForm.dimension} onChange={e=>setUnitForm({...unitForm,dimension:e.target.value})}><option value="count">Conteo</option><option value="mass">Peso</option><option value="length">Longitud</option><option value="volume">Volumen</option><option value="area">Área</option><option value="time">Tiempo</option></select></label><label className="settings-field"><span>Precisión decimal</span><input type="number" min="0" max="6" value={unitForm.precision_scale} onChange={e=>setUnitForm({...unitForm,precision_scale:e.target.value})}/></label><label className="settings-field product-phase2-checkbox"><span><input type="checkbox" checked={unitForm.is_base} onChange={e=>setUnitForm({...unitForm,is_base:e.target.checked})}/> Unidad base</span></label></div><button className="settings-primary-button" disabled={busy}><Plus size={15}/>Agregar unidad</button></form><div className="product-phase2-unit-list">{units.map(unit=><span key={unit.id}>{unit.name} ({unit.unit_code}) · {unit.dimension}{unit.is_base?' · Base':''}</span>)}</div><form className="product-phase2-form" onSubmit={addConversion}><h3>Nueva conversión dirigida</h3><div className="settings-form-grid"><label className="settings-field"><span>Desde</span><select required value={conversionForm.from_unit_id} onChange={e=>setConversionForm({...conversionForm,from_unit_id:e.target.value})}><option value="">Selecciona unidad</option>{units.map(unit=><option key={unit.id} value={unit.id}>{unit.name} ({unit.unit_code})</option>)}</select></label><label className="settings-field"><span>Hacia</span><select required value={conversionForm.to_unit_id} onChange={e=>setConversionForm({...conversionForm,to_unit_id:e.target.value})}><option value="">Selecciona unidad</option>{units.map(unit=><option key={unit.id} value={unit.id}>{unit.name} ({unit.unit_code})</option>)}</select></label><label className="settings-field"><span>Factor (1 desde = factor hacia)</span><input required type="number" min="0.0000000001" step="any" value={conversionForm.factor} onChange={e=>setConversionForm({...conversionForm,factor:e.target.value})}/></label><label className="settings-field"><span>Vigente desde</span><input required type="date" value={conversionForm.valid_from} onChange={e=>setConversionForm({...conversionForm,valid_from:e.target.value})}/></label><label className="settings-field product-editor-full"><span>Motivo si ya hay movimientos</span><input value={conversionForm.reason} onChange={e=>setConversionForm({...conversionForm,reason:e.target.value})}/></label></div><button className="settings-primary-button" disabled={busy}><Plus size={15}/>Guardar conversión</button></form><div className="product-phase2-conversion-check"><strong>Probar conversión vigente</strong><input aria-label="Cantidad a convertir" type="number" min="0" step="any" value={conversionAmount} onChange={e=>setConversionAmount(e.target.value)}/><select value={conversionForm.from_unit_id} onChange={e=>setConversionForm({...conversionForm,from_unit_id:e.target.value})}><option value="">Desde</option>{units.map(unit=><option key={unit.id} value={unit.id}>{unit.unit_code}</option>)}</select><select value={conversionForm.to_unit_id} onChange={e=>setConversionForm({...conversionForm,to_unit_id:e.target.value})}><option value="">Hacia</option>{units.map(unit=><option key={unit.id} value={unit.id}>{unit.unit_code}</option>)}</select><button className="settings-secondary-button" disabled={busy} onClick={()=>void runConversion()}>Convertir</button>{conversionResult&&<output>{conversionResult}</output>}</div><div className="product-phase2-list">{conversions.map(conversion=><article key={conversion.id}><div><strong>1 {conversion.from_unit_code} = {conversion.factor} {conversion.to_unit_code}</strong><small>Desde {String(conversion.valid_from).slice(0,10)} · {conversion.status}{conversion.reason?` · ${conversion.reason}`:''}</small></div>{conversion.status==='pending'&&canApproveConversions&&<button className="settings-secondary-button" disabled={busy} onClick={()=>void approveConversion(conversion.id)}>Aprobar (Inventario)</button>}</article>)}</div></>:<p className="settings-modal-note">Guarda el producto para configurar unidades y conversiones.</p>}</div>}
    {activeTab==='logistics'&&<div className="product-phase2-panel"><header className="product-phase2-heading"><div><h2>Perfil logístico vigente</h2><p>Los cambios crean una nueva versión con fecha de vigencia; las dimensiones no modifican existencias.</p></div>{logisticsForm.valid_from&&<small>Vigente desde {String(logisticsForm.valid_from).slice(0,10)}</small>}</header>{productId?<><form className="product-phase2-form" onSubmit={saveLogistics}><div className="settings-form-grid">{[['net_weight','Peso neto'],['gross_weight','Peso bruto'],['length','Largo'],['width','Ancho'],['height','Alto'],['volume','Volumen (vacío = calcular)'],['units_per_box','Unidades por caja'],['units_per_package','Unidades por paquete'],['units_per_pallet','Unidades por pallet']].map(([key,label])=><label className="settings-field" key={key}><span>{label}</span><input type="number" min="0" step="any" value={logisticsForm[key]??''} onChange={e=>setLogisticsForm({...logisticsForm,[key]:e.target.value})}/></label>)}<label className="settings-field"><span>Unidad de peso</span><select value={logisticsForm.weight_unit||'kg'} onChange={e=>setLogisticsForm({...logisticsForm,weight_unit:e.target.value})}><option value="kg">kg</option><option value="g">g</option><option value="lb">lb</option><option value="oz">oz</option></select></label><label className="settings-field"><span>Unidad dimensional</span><select value={logisticsForm.dimension_unit||'cm'} onChange={e=>setLogisticsForm({...logisticsForm,dimension_unit:e.target.value})}><option value="mm">mm</option><option value="cm">cm</option><option value="m">m</option><option value="in">in</option></select></label><label className="settings-field"><span>Embalaje</span><input value={logisticsForm.packaging_type||''} onChange={e=>setLogisticsForm({...logisticsForm,packaging_type:e.target.value})}/></label><label className="settings-field"><span>Apilable</span><select value={logisticsForm.stackable==null?'':String(logisticsForm.stackable)} onChange={e=>setLogisticsForm({...logisticsForm,stackable:e.target.value===''?null:e.target.value==='true'})}><option value="">Sin definir</option><option value="true">Sí</option><option value="false">No</option></select></label><label className="settings-field"><span>Manipulación especial</span><textarea rows={3} value={logisticsForm.handling_requirements||''} onChange={e=>setLogisticsForm({...logisticsForm,handling_requirements:e.target.value})}/></label><label className="settings-field"><span>Condiciones de almacenamiento</span><textarea rows={3} value={logisticsForm.storage_conditions||''} onChange={e=>setLogisticsForm({...logisticsForm,storage_conditions:e.target.value})}/></label></div><button className="settings-primary-button" disabled={busy}><Save size={15}/>Guardar perfil con nueva vigencia</button></form>{logisticsHistory.length>1&&<div className="product-phase2-list"><h3>Versiones anteriores</h3>{logisticsHistory.slice(1).map(profile=><article key={profile.id}><div><strong>Vigente {String(profile.valid_from).slice(0,10)} – {profile.valid_until?String(profile.valid_until).slice(0,10):"actual"}</strong><small>{profile.net_weight??"—"} {profile.weight_unit} · {profile.length??"—"} × {profile.width??"—"} × {profile.height??"—"} {profile.dimension_unit} · {profile.created_by_name||"Usuario"}</small></div></article>)}</div>}</>:<p className="settings-modal-note">Guarda el producto para registrar su perfil logístico.</p>}</div>}
    {activeTab==='suppliers'&&<div className="product-phase2-panel"><header className="product-phase2-heading"><div><h2>Proveedores del producto</h2><p>Registra referencias, MOQ, plazo y costo cotizado como condición comercial; no reemplaza el costo contabilizado.</p></div></header>{productId?<><form className="product-phase2-form" onSubmit={addSupplierLink}><div className="settings-form-grid"><label className="settings-field"><span>Proveedor *</span><select required value={supplierForm.supplier_id||''} onChange={e=>setSupplierForm({...supplierForm,supplier_id:e.target.value})}><option value="">Seleccionar proveedor</option>{supplierOptions.map(s=><option key={s.id} value={s.id}>{s.name}{s.country?` · ${s.country}`:''}</option>)}</select></label><label className="settings-field"><span>Código del proveedor</span><input value={supplierForm.supplier_product_code||''} onChange={e=>setSupplierForm({...supplierForm,supplier_product_code:e.target.value})}/></label><label className="settings-field"><span>Nombre del producto en origen</span><input value={supplierForm.supplier_product_name||''} onChange={e=>setSupplierForm({...supplierForm,supplier_product_name:e.target.value})}/></label><label className="settings-field"><span>Costo cotizado</span><input type="number" min="0" step="0.000001" value={supplierForm.quoted_unit_cost??''} onChange={e=>setSupplierForm({...supplierForm,quoted_unit_cost:e.target.value})}/></label><label className="settings-field"><span>Moneda</span><select value={supplierForm.currency||'USD'} onChange={e=>setSupplierForm({...supplierForm,currency:e.target.value})}>{['USD','EUR','GBP','CNY','COP','MXN','PEN'].map(c=><option key={c}>{c}</option>)}</select></label><label className="settings-field"><span>MOQ</span><input type="number" min="0.000001" step="any" value={supplierForm.minimum_order_quantity??''} onChange={e=>setSupplierForm({...supplierForm,minimum_order_quantity:e.target.value})}/></label><label className="settings-field"><span>Plazo (días)</span><input type="number" min="0" step="1" value={supplierForm.lead_time_days??''} onChange={e=>setSupplierForm({...supplierForm,lead_time_days:e.target.value})}/></label><label className="settings-field"><span>País de origen</span><input value={supplierForm.origin_country||''} onChange={e=>setSupplierForm({...supplierForm,origin_country:e.target.value})}/></label><label className="settings-field"><span>Unidad de compra</span><input value={supplierForm.purchase_unit||''} onChange={e=>setSupplierForm({...supplierForm,purchase_unit:e.target.value})}/></label><label className="settings-field"><span>Empaque</span><input value={supplierForm.packaging||''} onChange={e=>setSupplierForm({...supplierForm,packaging:e.target.value})}/></label><label className="settings-field"><span>Vigente desde *</span><input type="date" required value={supplierForm.valid_from} onChange={e=>setSupplierForm({...supplierForm,valid_from:e.target.value})}/></label><label className="settings-field"><span>Vigente hasta</span><input type="date" value={supplierForm.valid_until||''} onChange={e=>setSupplierForm({...supplierForm,valid_until:e.target.value})}/></label><label className="settings-field"><span><input type="checkbox" checked={Boolean(supplierForm.is_preferred)} onChange={e=>setSupplierForm({...supplierForm,is_preferred:e.target.checked})}/> Proveedor preferido</span></label><label className="settings-field product-editor-full"><span>Notas</span><textarea rows={2} value={supplierForm.notes||''} onChange={e=>setSupplierForm({...supplierForm,notes:e.target.value})}/></label></div><button className="settings-primary-button" disabled={busy}><Plus size={15}/>Guardar referencia de proveedor</button></form><div className="product-phase2-list">{supplierLinks.map(link=><article key={link.id}><div><strong>{link.supplier_name}{link.is_preferred?' · Preferido':''}</strong><small>{link.supplier_product_code||'Sin código proveedor'} · {link.quoted_unit_cost==null?'Costo no informado':`${link.currency} ${link.quoted_unit_cost}`} · MOQ {link.minimum_order_quantity??'—'} · Plazo {link.lead_time_days??'—'} días</small><small>Vigencia {String(link.valid_from).slice(0,10)} a {link.valid_until?String(link.valid_until).slice(0,10):'actual'}{link.purchase_unit?` · ${link.purchase_unit}`:''}{link.packaging?` · ${link.packaging}`:''}</small></div></article>)}{!supplierLinks.length&&<p className="settings-modal-note">Aún no hay proveedores vinculados.</p>}</div></>:<p className="settings-modal-note">Guarda el producto antes de asociar proveedores.</p>}</div>}
    {activeTab==='import-classification'&&<div className="product-phase2-panel"><header className="product-phase2-heading"><div><h2>Clasificación de importación</h2><p>La partida propuesta se conserva con fuente, evidencia y vigencia. Nunca se presume correcta: requiere revisión de Importaciones.</p></div></header>{productId?<><form className="product-phase2-form" onSubmit={submitClassification}><div className="settings-form-grid"><label className="settings-field"><span>Partida arancelaria *</span><input required value={classificationForm.tariff_heading||''} onChange={e=>setClassificationForm({...classificationForm,tariff_heading:e.target.value})} placeholder="4, 6, 8 o 10 dígitos"/></label><label className="settings-field"><span>Subpartida</span><input value={classificationForm.tariff_subheading||''} onChange={e=>setClassificationForm({...classificationForm,tariff_subheading:e.target.value})}/></label><label className="settings-field"><span>País de origen</span><input value={classificationForm.origin_country||''} onChange={e=>setClassificationForm({...classificationForm,origin_country:e.target.value})}/></label><label className="settings-field"><span>País de fabricación</span><input value={classificationForm.manufacturing_country||''} onChange={e=>setClassificationForm({...classificationForm,manufacturing_country:e.target.value})}/></label><label className="settings-field"><span>Fabricante extranjero</span><input value={classificationForm.foreign_manufacturer||''} onChange={e=>setClassificationForm({...classificationForm,foreign_manufacturer:e.target.value})}/></label><label className="settings-field"><span>Unidad comercial aduanera</span><input value={classificationForm.customs_unit||''} onChange={e=>setClassificationForm({...classificationForm,customs_unit:e.target.value})}/></label><label className="settings-field"><span>Peso documental</span><input type="number" min="0" step="any" value={classificationForm.customs_weight??''} onChange={e=>setClassificationForm({...classificationForm,customs_weight:e.target.value})}/></label><label className="settings-field"><span>Vigente desde *</span><input type="date" required value={classificationForm.valid_from} onChange={e=>setClassificationForm({...classificationForm,valid_from:e.target.value})}/></label><label className="settings-field"><span>Vigente hasta</span><input type="date" value={classificationForm.valid_until||''} onChange={e=>setClassificationForm({...classificationForm,valid_until:e.target.value})}/></label><label className="settings-field"><span>Fuente de clasificación *</span><input required value={classificationForm.source_name||''} onChange={e=>setClassificationForm({...classificationForm,source_name:e.target.value})} placeholder="Resolución, criterio técnico…"/></label><label className="settings-field"><span>Enlace de fuente</span><input type="url" value={classificationForm.source_url||''} onChange={e=>setClassificationForm({...classificationForm,source_url:e.target.value})}/></label><label className="settings-field"><span>Evidencia documental (desde PC)</span><input type="file" accept="image/*,.pdf,.docx,.xlsx,.txt" onChange={e=>void uploadClassificationEvidence(e)}/>{classificationForm.evidence_url&&<a href={classificationForm.evidence_url} target="_blank" rel="noreferrer">Ver archivo cargado</a>}</label><label className="settings-field product-editor-full"><span>Restricciones</span><textarea rows={2} value={classificationForm.import_restrictions||''} onChange={e=>setClassificationForm({...classificationForm,import_restrictions:e.target.value})}/></label><label className="settings-field product-editor-full"><span>Permisos y certificados requeridos</span><textarea rows={2} value={classificationForm.required_permits||''} onChange={e=>setClassificationForm({...classificationForm,required_permits:e.target.value})}/></label><label className="settings-field product-editor-full"><span>Observaciones aduaneras</span><textarea rows={2} value={classificationForm.customs_notes||''} onChange={e=>setClassificationForm({...classificationForm,customs_notes:e.target.value})}/></label></div><button className="settings-primary-button" disabled={busy||uploading}><Plus size={15}/>Enviar a revisión</button></form><div className="product-phase2-list">{classificationRecords.map(record=><article key={record.id}><div><strong>{record.tariff_heading}{record.tariff_subheading?` · ${record.tariff_subheading}`:''} · {record.review_status==='approved'?'Aprobada':record.review_status==='rejected'?'Rechazada':record.review_status==='superseded'?'Reemplazada':'Pendiente'}</strong><small>{record.source_name} · vigente {String(record.valid_from).slice(0,10)} a {record.valid_until?String(record.valid_until).slice(0,10):'sin fecha final'} · propuesta por {record.creator_name||'Usuario'}</small>{record.evidence_url&&<a href={record.evidence_url} target="_blank" rel="noreferrer">Abrir evidencia</a>}{record.review_reason&&<small>{record.review_reason}</small>}</div>{record.review_status==='pending'&&canReviewClassification&&<div className="product-row-actions"><button className="settings-primary-button" disabled={busy} onClick={()=>void reviewClassification(record.id,'approved')}>Aprobar</button><button className="settings-secondary-button" disabled={busy} onClick={()=>void reviewClassification(record.id,'rejected')}>Rechazar</button></div>}</article>)}{!classificationRecords.length&&<p className="settings-modal-note">Aún no hay clasificaciones propuestas. Los datos existentes en la pestaña Importación no se tratan como aprobados automáticamente.</p>}</div></>:<p className="settings-modal-note">Guarda el producto antes de solicitar una clasificación arancelaria.</p>}</div>}
    {detailTabs.some(tab=>tab.id===activeTab&&!['variants','units','logistics','suppliers','import-classification'].includes(tab.id))&&<div className="settings-form-grid">{detailTabs.find(tab=>tab.id===activeTab)?.fields.map(([key,label])=><label className="settings-field" key={key}><span>{label}</span>{['price_lists','handling_requirements','storage_conditions','import_restrictions','required_permits','customs_notes','attributable_costs','cost_notes'].includes(key)?<textarea rows={3} value={form.details?.[key]||''} onChange={e=>updateDetail(key,e.target.value)}/>:<input type={['price_valid_from','price_valid_until'].includes(key)?'date':['units_per_box','units_per_package','units_per_pallet','decimal_precision','retail_price','distributor_price','allowed_discount','minimum_price','target_margin','reference_acquisition_cost','last_purchase_cost','average_cost','landed_import_cost','customs_weight'].includes(key)?'number':'text'} min="0" step="any" value={form.details?.[key]??''} onChange={e=>updateDetail(key,e.target.value)}/>}</label>)}</div>}
    {activeTab==='media'&&productId&&<div className="product-phase2-panel"><header className="product-phase2-heading"><div><h2>Fotografías y documentos versionados</h2><p>Los archivos se guardan de forma privada. Reemplazar crea otra versión y conserva las anteriores.</p></div></header><form className="product-phase2-form" onSubmit={e=>e.preventDefault()}><div className="settings-form-grid"><label className="settings-field"><span>Tipo de archivo</span><select value={mediaForm.media_type} onChange={e=>setMediaForm({...mediaForm,media_type:e.target.value})}><option value="primary_image">Fotografía principal</option><option value="gallery">Galería</option><option value="technical_sheet">Ficha técnica</option><option value="manual">Manual</option><option value="certificate">Certificado</option><option value="warranty">Garantía</option><option value="safety_sheet">Hoja de seguridad</option><option value="manufacturer_document">Documento del fabricante</option><option value="other">Otro</option></select></label><label className="settings-field"><span>Descripción</span><input value={mediaForm.description} onChange={e=>setMediaForm({...mediaForm,description:e.target.value})}/></label><label className="settings-field"><span>Orden de presentación</span><input type="number" min="0" step="1" value={mediaForm.sort_order} onChange={e=>setMediaForm({...mediaForm,sort_order:e.target.value})}/></label><label className="settings-field"><span><input type="checkbox" checked={mediaForm.is_primary} onChange={e=>setMediaForm({...mediaForm,is_primary:e.target.checked})}/> Marcar como fotografía principal</span></label><label className="settings-field product-editor-full"><span>Subir archivo desde este PC</span><input type="file" accept="image/*,.pdf,.docx,.xlsx,.txt" disabled={uploading} onChange={e=>void uploadProductMedia(e)}/></label></div>{uploading&&<small>Subiendo archivo…</small>}</form><div className="product-phase2-list">{mediaRecords.map(media=><article key={media.id}><div><strong>{media.media_type}{media.is_primary?' · Principal':''}{media.description?` · ${media.description}`:''}</strong><small>{media.versions?.length||0} versión(es) · archivo actual: {media.versions?.[0]?.original_filename||'—'} · checksum SHA-256 {media.versions?.[0]?.checksum_sha256?.slice(0,12)||'—'}</small><div className="product-row-actions"><button type="button" className="settings-secondary-button" disabled={!media.current_version_id} onClick={()=>void openMediaVersion(media.id,media.current_version_id)}>Ver / descargar</button><label className="settings-secondary-button">Reemplazar<input type="file" hidden accept="image/*,.pdf,.docx,.xlsx,.txt" disabled={uploading} onChange={e=>void uploadProductMedia(e,media.id)}/></label><button type="button" className="settings-secondary-button" disabled={busy} onClick={()=>void archiveMedia(media.id)}>Archivar</button></div>{media.versions?.length>1&&<details><summary>Versiones anteriores</summary>{media.versions.slice(1).map((version:any)=><button type="button" key={version.id} className="settings-text-button" onClick={()=>void openMediaVersion(media.id,version.id)}>v{version.version_number} · {version.original_filename} · {new Date(version.created_at).toLocaleString('es-EC')}</button>)}</details>}</div></article>)}{!mediaRecords.length&&<p className="settings-modal-note">Este producto aún no tiene archivos asociados.</p>}</div>{mediaPreview&&<div className="product-media-preview"><button type="button" className="settings-secondary-button" onClick={()=>{URL.revokeObjectURL(mediaPreview.url);setMediaPreview(null);}}>Cerrar vista previa</button>{mediaPreview.mime.startsWith('image/')?<img src={mediaPreview.url} alt="Vista previa del archivo"/>:<p>{mediaPreview.name}</p>}<a href={mediaPreview.url} download>Descargar archivo</a></div>}</div>}    {activeTab==='media'&&!productId&&<div className="settings-form-grid"><label className="settings-field"><span>Fotografía principal</span><input type="file" accept="image/jpeg,image/png,image/webp,image/avif" disabled={Boolean(productId)} onChange={e=>void uploadFile('image_url',e.target.files?.[0])}/>{productId&&<small>Para reemplazarla con historial, usa Fotos y documentos.</small>}{uploading&&<small>Subiendo…</small>}{form.image_url&&<img className="product-editor-image-preview" src={form.image_url} alt="Fotografía del producto"/>}</label>{[['gallery','Galería'],['technical_sheets','Fichas técnicas'],['manuals','Manuales'],['certificates','Certificados'],['warranties','Garantías'],['safety_sheets','Hojas de seguridad'],['manufacturer_documents','Documentos del fabricante']].map(([key,label])=><label className="settings-field" key={key}><span>{label}</span><input type="file" multiple accept="image/*,.pdf,.docx,.xlsx,.txt" onChange={e=>{const files=[...e.target.files||[]];files.forEach(file=>void uploadFile(key,file));}}/><div className="product-editor-file-list">{(form.details?.[key]||[]).map((file:any)=><a key={file.url} href={file.url} target="_blank" rel="noreferrer">{file.name||file.url}</a>)}</div></label>)}</div>}
   </div>{error&&<p className="settings-message error product-form-error">{error}</p>}{notice&&<p className="settings-message success">{notice}</p>}<footer>{productId&&<label className="settings-field product-editor-reason"><span>Motivo del cambio *</span><input required value={form.change_reason||''} onChange={e=>setForm({...form,change_reason:e.target.value})}/></label>}<button type="button" className="settings-secondary-button" onClick={()=>router.push('/products')}>Cancelar</button>{canWrite&&<button className="settings-primary-button" disabled={busy||uploading}><Save size={16}/>{busy?'Guardando…':uploading?'Subiendo…':productId?'Guardar cambios':'Crear producto'}</button>}</footer></form>}
  </section>}
 </main></div>;
}
